    fn assert_close(actual: f32, expected: f32) {
        assert!(
            (actual - expected).abs() < 1e-5,
            "{actual:.8} != {expected:.8}"
        );
    }

    fn assert_close_with_tolerance(actual: f32, expected: f32, tolerance: f32) {
        assert!(
            (actual - expected).abs() <= tolerance,
            "{actual:.8} != {expected:.8} within {tolerance:.8}"
        );
    }

